  "Create new profile": "Tạo hồ sơ mới",
  "This browser doesn't do passkeys, but you can still use openGym locally on this device.": "Trình duyệt này không cung cấp mật khẩu nhưng bạn vẫn có thể sử dụng openGym cục bộ trên thiết bị này.",
  "This browser doesn't support passkeys, and this instance requires an account. Try a browser or device with passkey support.": "Trình duyệt này không hỗ trợ mật mã và phiên bản này yêu cầu phải có tài khoản. Hãy thử trình duyệt hoặc thiết bị có hỗ trợ mật mã.",
  "Continue without account": "Tiếp tục mà không cần tài khoản",
