  "Sign in with password": "Đăng nhập bằng mật khẩu",
  "Password": "Mật khẩu",
  "Passkeys use {0}. A password works too, where passkeys do not.": "Mật mã sử dụng {0}. Mật khẩu cũng có tác dụng trong khi mật khẩu thì không.",
  "This browser doesn't support passkeys. Sign in with your name and password instead.": "Trình duyệt này không hỗ trợ mật mã. Thay vào đó hãy đăng nhập bằng tên và mật khẩu của bạn.",
