  "Enter the code your admin gave you and choose a new password. It signs you out everywhere else.": "Nhập mã mà quản trị viên đã cung cấp cho bạn và chọn mật khẩu mới. Nó đăng bạn ra ở mọi nơi khác.",
  "Reset code": "Đặt lại mã",
