  "Repeat the password": "Lặp lại mật khẩu",
  "Current password": "Mật khẩu hiện tại",
  "Use your profile name (or the e-mail you added to it) and your password.": "Sử dụng tên hồ sơ của bạn (hoặc e-mail bạn đã thêm vào đó) và mật khẩu của bạn.",
  "Name or e-mail": "Tên hoặc e-mail",
