  "E-mail (optional)": "Email (tùy chọn)",
  "Lets you sign in with it instead of your name. Nothing is ever sent to it.": "Cho phép bạn đăng nhập bằng nó thay vì tên của bạn. Không có gì được gửi đến nó.",
  "That is not an e-mail address.": "Đó không phải là một địa chỉ email.",
  "Another profile already uses this e-mail address.": "Một hồ sơ khác đã sử dụng địa chỉ email này.",
  "Sign-in e-mail": "Email đăng nhập",
  "Sign in with “{0}” instead of your name": "Đăng nhập bằng “{0}” thay vì tên của bạn",
  "“{0}” is saved, but signs in only once this profile has a password.": "“{0}” được lưu nhưng chỉ đăng nhập khi hồ sơ này có mật khẩu.",
  "Not set. Lets you sign in with an e-mail instead of your name.": "Chưa được thiết lập. Cho phép bạn đăng nhập bằng e-mail thay vì tên của bạn.",
