  "Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.": "Nhập nó vào “Đăng nhập bằng mật khẩu” thay vì tên hồ sơ của bạn. Chúng tôi không bao giờ gửi bất cứ thứ gì tới nó; mật khẩu bị quên vẫn được quản trị viên của bạn đặt lại.",
  "E-mail address": "Địa chỉ email",
