  "Remove your sign-in e-mail?": "Xóa e-mail đăng nhập của bạn?",
  "Afterwards you sign in with your profile name only.": "Sau đó, bạn chỉ đăng nhập bằng tên hồ sơ của mình.",
  "E-mail removed": "Email đã bị xóa",
  "Too many attempts. Try again {0}.": "Quá nhiều nỗ lực. Hãy thử lại {0}.",
