  "That password is too long.": "Mật khẩu đó quá dài.",
  "That password is too easy to guess. Try a longer one, or a few random words strung together.": "Mật khẩu đó quá dễ đoán. Hãy thử một từ dài hơn hoặc một vài từ ngẫu nhiên được xâu chuỗi lại với nhau.",
  "Another profile already signs in with this name.": "Một hồ sơ khác đã đăng nhập bằng tên này.",
  "That invite code is not valid.": "Mã mời đó không hợp lệ.",
  "Your current password is not right.": "Mật khẩu hiện tại của bạn không đúng.",
  "Your passkey could not be confirmed.": "Không thể xác nhận mật mã của bạn.",
  "This password is the only way into your profile, so it cannot be removed.": "Mật khẩu này là cách duy nhất để vào hồ sơ của bạn nên không thể xóa được.",
  "That reset code is wrong or has expired. Ask your admin for a new one.": "Mã đặt lại đó sai hoặc đã hết hạn. Hãy hỏi quản trị viên của bạn để có một cái mới.",
  "This account has been disabled.": "Tài khoản này đã bị vô hiệu hóa.",
  "The server is busy. Try again in a moment.": "Máy chủ đang bận. Hãy thử lại sau giây lát.",
  "1 passkey": "1 mật khẩu",
  "A one-time code lets your phone or another computer sign in with a passkey of its own.": "Mã một lần cho phép điện thoại của bạn hoặc một máy tính khác đăng nhập bằng mật mã riêng.",
  "Add a passkey": "Thêm mật mã",
  "Add another device": "Thêm thiết bị khác",
  "Add this device": "Thêm thiết bị này",
  "Added {0}": "Đã thêm {0}",
  "Code from your other device": "Mã từ thiết bị khác của bạn",
  "Confirm with a passkey": "Xác nhận bằng mật mã",
  "Confirmed. Now create the new passkey; your browser will ask where to keep it.": "Đã xác nhận. Bây giờ hãy tạo mật mã mới; trình duyệt của bạn sẽ hỏi nơi lưu trữ nó.",
  "Copy link": "Sao chép liên kết",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "Tạo mật mã trên thiết bị này cho cấu hình “{0}”. Nó báo hiệu bạn ở đây kể từ bây giờ.",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "Mỗi người đăng nhập vào hồ sơ này từ thiết bị hoặc trình quản lý mật khẩu lưu giữ hồ sơ đó. Nhấn vào một cái để đổi tên hoặc xóa nó.",
  "Enter the code from your other device.": "Nhập mã từ thiết bị khác của bạn.",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "Đối với thiết bị này, khóa bảo mật, trình quản lý mật khẩu hoặc điện thoại của bạn thông qua mã QR riêng của trình duyệt. Đầu tiên hãy xác nhận rằng đó là bạn.",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "Nó không thể đăng nhập vào hồ sơ này nữa. Thiết bị đã đăng nhập bằng thiết bị đó vẫn duy trì trạng thái đăng nhập. Nếu thiết bị bị mất, hãy sử dụng Đăng xuất ở mọi nơi.",
  "It is your only way in, so it cannot be removed until there is another.": "Đó là lối vào duy nhất của bạn, vì vậy nó không thể bị loại bỏ cho đến khi có một lối khác.",
  "Last used {0}": "{0} được sử dụng lần cuối",
  "Make a new code": "Tạo mã mới",
  "Name, e.g. Work laptop": "Tên, ví dụ: Máy tính xách tay làm việc",
  "None yet. Add one and sign in without your password.": "Chưa có. Thêm một và đăng nhập mà không cần mật khẩu của bạn.",
  "Passkey added": "Đã thêm mật khẩu",
  "Passkey removed": "Đã xóa mật khẩu",
  "Passkey {0}": "Mã khóa {0}",
  "Passkeys": "Mật mã",
  "Remove passkey": "Xóa mật mã",
  "Remove this passkey?": "Xóa mật mã này?",
  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "Quét thiết bị này bằng thiết bị khác hoặc mở openGym ở đó và nhập mã trên màn hình đăng nhập. Nó hoạt động một lần, trong vài phút {0}.",
  "That code is wrong, already used or expired. Make a new one on your other device.": "Mã đó sai, đã được sử dụng hoặc hết hạn. Tạo một cái mới trên thiết bị khác của bạn.",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "Trình duyệt này không thể xác nhận bằng mật mã của bạn. Thực hiện việc này trên một thiết bị có chứa một thiết bị.",
  "First confirm that it is you.": "Đầu tiên hãy xác nhận rằng đó là bạn.",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "Hồ sơ này không có mật khẩu và máy chủ này không lấy mật khẩu nên không có gì ở đây có thể xác nhận rằng đó là bạn. Hãy hỏi quản trị viên của bạn.",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "Trình duyệt này không thể tạo mật mã nên không thể thêm mã vào. Mở liên kết trong một trình duyệt có thể.",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "Trình duyệt này được đăng nhập với tên “{0}”. Việc thêm nó vào “{1}” sẽ ký hiệu “{0}” tại đây.",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "Mã này dành cho một hồ sơ khác còn được gọi là “{0}”, không phải hồ sơ mà trình duyệt này dùng để đăng nhập. Thêm nó vào đó ký tên của bạn ở đây.",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "Chỉ tiếp tục nếu mã này đến từ thiết bị của riêng bạn. Sau đó, trình duyệt này được đăng nhập vào “{0}” và nội dung bạn đăng nhập ở đây sẽ chuyển đến hồ sơ đó.",
  "This code has expired.": "Mã này đã hết hạn.",
  "This device already has a passkey for this profile.": "Thiết bị này đã có mật mã cho hồ sơ này.",
  "This passkey already belongs to a profile.": "Mật mã này đã thuộc về một hồ sơ.",
  "This profile already has as many passkeys as it can hold.": "Hồ sơ này đã có nhiều mật khẩu nhất có thể.",
  "Use a code from your other device": "Sử dụng mã từ thiết bị khác của bạn",
  "You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.": "Bạn nhận được mã cho phép điện thoại của bạn hoặc máy tính khác tạo mật mã cho cấu hình này. Đầu tiên hãy xác nhận rằng đó là bạn.",
