  "Missed reps. {0} {1} of help while you build back up.": "Số đại diện bị bỏ lỡ. {0} {1} trợ giúp trong khi bạn xây dựng lại.",
  "Stuck for {0} sessions. Back to {1} {2} of help, then build up again.": "Bị kẹt trong các phiên {0}. Quay lại {1} {2} để được trợ giúp rồi build lại.",
  "Missed reps {0} sessions running. Reset to {1} {2} and work back up.": "Các phiên {0} đang chạy số lần lặp lại bị bỏ lỡ. Đặt lại về {1} {2} và sao lưu.",
