  "Add time": "Thêm thời gian",
  "Targets stay where you set them.": "Mục tiêu vẫn ở nơi bạn đặt chúng.",
  "Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.": "Đánh từng lần lặp lại trong mỗi hiệp và trọng lượng sẽ tăng lên. Việc bỏ lỡ lặp đi lặp lại sẽ kích hoạt quá trình tải xuống.",
  "Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.": "Hai set thẳng cộng với một set cuối cùng dẫn đến thất bại. Đánh bại mục tiêu trong hiệp đó và mức tạ sẽ tăng lên (gấp đôi nếu bạn tăng gấp đôi số lần). Một lần thất bại sẽ đặt lại 10%.",
  "Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.": "Tập luyện với số lần lặp ở cùng mức tạ. Đạt đến đỉnh của phạm vi trong mỗi hiệp và mức tạ tăng lên, số lần lặp lại sẽ giảm xuống mức thấp nhất.",
