  "How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.": "Một hiệp đấu khó đến mức nào, được ghi bên cạnh trọng lượng và số lần lặp lại. Hai thang đo cho cùng một phán đoán, được tính từ hai đầu đối diện.",
