  "Clear rating": "Đánh giá rõ ràng",
  "RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.": "RIR đếm số lần bạn còn lại trong bể; RPE thể hiện nỗ lực tương tự theo thang điểm 10, do đó RPE ≈ 10 − RIR. Chọn bất cứ điều gì bạn đã nghĩ đến.",
  "The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.": "Hàng được đánh dấu là nơi hầu hết các nhóm làm việc đều diễn ra. Các bộ bạn đã ghi sẽ giữ tỷ lệ riêng và không có gì khác đọc giá trị, do đó tiến trình và 1RM ước tính không bị ảnh hưởng.",
