  "You are only notified when the Coach actually has something to suggest.": "Bạn chỉ được thông báo khi Huấn luyện viên thực sự có điều gì đó muốn đề xuất.",
  "On this phone the Coach can only look while the app is open: right after a workout, or the next time you open it.": "Trên điện thoại này, Huấn luyện viên chỉ có thể xem khi ứng dụng đang mở: ngay sau khi tập luyện hoặc vào lần tiếp theo bạn mở ứng dụng.",
