  "Where the sets land": "Nơi bộ đất hạ cánh",
  "Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.": "Hầu hết các bộ công việc đều gần như thất bại chứ không phải ở mức đó. Một nửa ở dưới sàn và một nửa ở trên cùng vẫn đạt mức trung bình ở giữa trông khỏe mạnh.",
  "Average effort per workout": "Nỗ lực trung bình mỗi lần tập luyện",
  "A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.": "Dấu chấm đầy đủ hơn có nghĩa là còn lại ít hơn trong bể. Trọng lượng tương tự ở {0} thấp hơn là tiến trình mà chỉ riêng dòng không hiển thị.",
  "No weight to enter. Just log the reps.": "Không có trọng lượng để nhập. Chỉ cần đăng nhập các đại diện.",
  "Ask for a weight on every set.": "Yêu cầu trọng lượng trên mỗi bộ.",
  "For dips or pull-ups with a belt. Progression then follows the weight.": "Để thực hiện động tác nhúng hoặc kéo xà bằng dây đai. Sự tiến triển sau đó theo trọng lượng.",
  "For lunges, single-arm rows and the like.": "Đối với lunges, hàng một tay và những thứ tương tự.",
  "Top of the range": "Đầu phạm vi",
  "Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.": "Số đại diện sẽ tăng lên từng hiệp một bất cứ khi nào mỗi hiệp đều sạch sẽ. Đặt mức trần để thêm hiệp thay vì số lần lặp lại mãi mãi.",
  "Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.": "Các lần lặp lại leo lên {0}, sau đó một hiệp được thêm vào và các lần lặp lại bắt đầu lại. Tại bộ {1}, nó sẽ yêu cầu bạn thêm trọng lượng.",
  "After how many workouts": "Sau bao nhiêu lần tập luyện",
  "applied": "áp dụng",
  "declined": "từ chối",
