  "How long is a session?": "Một buổi kéo dài bao lâu?",
  "min": "phút",
  "The Coach fits the volume to the time you actually have, including rest between sets.": "Huấn luyện viên điều chỉnh âm lượng phù hợp với thời gian bạn thực sự có, bao gồm cả thời gian nghỉ giữa các hiệp.",
  "What can you train with?": "Bạn có thể tập luyện bằng gì?",
  "Pick everything you have access to. Leave it empty and the Coach will use the whole library.": "Chọn mọi thứ bạn có quyền truy cập. Để trống và Huấn luyện viên sẽ sử dụng toàn bộ thư viện.",
  "Anything to work around?": "Có việc gì cần giải quyết không?",
  "Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.": "Chấn thương, khớp kêu khó chịu, những cử động bạn không thể thực hiện hoặc những giới hạn thực tế như tập luyện lúc 6 giờ sáng trong căn hộ.",
  "e.g. “dodgy left shoulder, no barbell overhead press”": "ví dụ. “Vai trái lắt léo, không có tạ đòn trên đầu”",
  "If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.": "Nếu có điều gì đó thực sự khiến bạn đau, hãy đến gặp chuyên gia. Huấn luyện viên sẽ lập trình một cách thận trọng nhưng không thể chẩn đoán bất cứ điều gì.",
  "Anything else?": "Còn gì nữa không?",
