  "Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.": "Local giữ mọi thứ trên điện thoại này. Thay vào đó, hãy kết nối đồng bộ hóa với máy chủ openGym của riêng bạn. Bạn có thể chuyển đổi sau trong Cài đặt.",
