  "reps": "đại diện",
  "Most reps in a set per workout": "Số lần lặp lại nhiều nhất trong một hiệp mỗi buổi tập",
  "Warm-up sets": "Bộ khởi động",
  "Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, never below the bar on a barbell lift, and you can still change any of them mid-session.": "Đã thêm vào trước tập công việc của bạn và loại bỏ khối lượng, bản ghi và tiến trình. Mỗi cái sẽ thu hẹp một nửa khoảng cách so với trọng lượng bài tập, không bao giờ thấp hơn thanh khi nâng tạ và bạn vẫn có thể thay đổi bất kỳ cái nào trong số chúng giữa buổi tập.",
  "Ramp-up sets added before the work sets, so you do not have to add them by hand each session.": "Các nhóm tăng tốc được thêm trước các nhóm công việc, do đó bạn không cần phải thêm chúng bằng tay vào mỗi phiên.",
  "Note": "Lưu ý",
  "This session": "Phiên này",
  "How it went, what to change. Saved with today’s workout.": "Mọi chuyện diễn ra như thế nào, cần thay đổi điều gì. Đã lưu với bài tập hôm nay.",
