  "Filters the exercise library and picker, and flags routine exercises that need something you don’t have in the active profile.": "Lọc thư viện và bộ chọn bài tập, đồng thời gắn cờ các bài tập thường lệ cần nội dung nào đó mà bạn không có trong hồ sơ hoạt động.",
