  "How did my last workout go?": "Buổi tập cuối cùng của tôi diễn ra thế nào?",
  "Focus only on my routine “{0}”. Improve it: exercise choice, order, sets and reps, rep ranges, progression. Leave the other routines alone.": "Chỉ tập trung vào thói quen “{0}” của tôi. Cải thiện nó: lựa chọn bài tập, thứ tự, số hiệp và số lần lặp lại, phạm vi số lần tập, sự tiến triển. Để lại các thói quen khác một mình.",
  "Improve my routine “{0}”.": "Cải thiện thói quen “{0}” của tôi.",
