  "Expired": "Đã hết hạn",
  "Your week was set to this schedule.": "Tuần của bạn đã được đặt theo lịch trình này.",
  "Use this plan in your rotation": "Sử dụng kế hoạch này trong vòng quay của bạn",
  "Replaces the sessions in your rotation and starts it over with the first one.": "Thay thế các phiên trong vòng quay của bạn và bắt đầu lại bằng phiên đầu tiên.",
  "Imported! {0} routines are in your plan and your rotation starts over with them. See you at the next session.": "Đã nhập khẩu! Các quy trình {0} nằm trong kế hoạch của bạn và vòng quay của bạn sẽ bắt đầu lại với chúng. Hẹn gặp lại các bạn ở buổi tiếp theo.",
  "Your rotation was set to this plan.": "Vòng xoay của bạn đã được đặt theo kế hoạch này.",
  "Imported without changing your week.": "Nhập khẩu mà không thay đổi tuần của bạn.",
  "This plan was imported before the app kept proposals; only its summary is left.": "Kế hoạch này đã được nhập trước khi ứng dụng lưu giữ các đề xuất; chỉ còn lại bản tóm tắt của nó.",
  "Applied {0} change to your plan.": "Đã áp dụng thay đổi {0} cho gói của bạn.",
