  "There’s no workout to look at yet. Log one first.": "Chưa có bài tập nào để xem. Đăng nhập một cái đầu tiên.",
  "Every planned set done: {0} of {1}.": "Mọi bộ theo kế hoạch đều được thực hiện: {0} của {1}.",
  "{0} of {1} planned sets done.": "{0} của {1} đã hoàn thành các bộ theo kế hoạch.",
  "{0} {1} moved in total.": "{0} {1} đã di chuyển tổng cộng.",
  "{0} new personal records.": "{0} hồ sơ cá nhân mới.",
  "{0} minutes is long. Rest periods may be creeping up.": "Số phút {0} dài. Thời gian nghỉ ngơi có thể tăng lên.",
  "Top sets logged without an effort rating; add RIR so the next review can read how hard they were.": "Các bộ hàng đầu được ghi lại mà không có xếp hạng nỗ lực; thêm RIR để lần đánh giá tiếp theo có thể biết được mức độ khó của chúng.",
  "Nothing yet. Every plan, suggestion and debrief will be kept here, whether you said yes or no.": "Chưa có gì. Mọi kế hoạch, đề xuất và báo cáo sẽ được lưu giữ ở đây, cho dù bạn có đồng ý hay không.",
  "Debrief: {0}": "Tóm tắt: {0}",
  "Could not load": "Không thể tải",
  "Could not save": "Không thể lưu",
  "Only medians across everyone who shares, never a name, a body weight or a single session. Turning this off removes you from the numbers immediately.": "Chỉ có mức trung bình đối với tất cả những người chia sẻ, không bao giờ có tên, trọng lượng cơ thể hoặc một phiên duy nhất. Việc tắt tính năng này sẽ loại bỏ bạn khỏi các con số ngay lập tức.",
  "Include me": "Bao gồm tôi",
