  "Not enough people are sharing yet ({0} of {1} needed). Rope in your gym mates!": "Chưa có đủ người chia sẻ (cần có {0} của {1}). Hãy tập thể dục nhé các bạn!",
  "Not available right now.": "Không có sẵn ngay bây giờ.",
  "People": "mọi người",
  "Your sessions / wk": "Phiên / tuần của bạn",
  "Median / wk": "Trung bình / tuần",
  "Your strength rank": "Thứ hạng sức mạnh của bạn",
  "Estimated 1RM, you vs. median": "Ước tính 1RM, bạn so với trung bình",
  "people": "mọi người",
  "You": "bạn",
  "Median": "trung vị",
  "No exercise is trained by three or more people yet.": "Chưa có bài tập nào được huấn luyện bởi ba người trở lên.",
  "Add the next load step on the main lift.": "Thêm bước tải tiếp theo vào thang máy chính.",
  "Repeat the same loads and get every set.": "Lặp lại các tải tương tự và nhận được mọi bộ.",
  "Keep the session under an hour and a quarter.": "Giữ phiên dưới một giờ và một phần tư.",
  "A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.": "Một phiên làm việc sạch sẽ: mọi thứ trên trang tính đã được hoàn thành và tải được giữ nguyên. Đây chính xác là sự tiến bộ trông như thế nào từ bên trong: không đáng kể, lặp đi lặp lại.",
  "Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.": "Hầu hết công việc đã hoàn thành. Một hoặc hai bộ bị hụt, một lần cũng không sao. Nó chỉ trở thành tín hiệu nếu lần sau các hiệp tương tự bị trượt.",
  "Get stronger": "Mạnh mẽ hơn",
