  "Custom": "tùy chỉnh",
  "Log your body weight to score this lift.": "Ghi lại trọng lượng cơ thể của bạn để ghi điểm cho lần nâng này.",
  "Log the anchor lift to score this one.": "Đăng nhập thang máy neo để ghi điểm này.",
  "Not scored": "Không được ghi điểm",
  "The server cannot be reached": "Máy chủ không thể kết nối được",
  "Your server can’t be reached. Your changes are saved on this device and sync once it answers again.": "Không thể truy cập máy chủ của bạn. Các thay đổi của bạn được lưu trên thiết bị này và đồng bộ hóa sau khi thiết bị trả lời lại.",
  "Your server can’t be reached. Showing the last copy synced with it.": "Không thể truy cập máy chủ của bạn. Hiển thị bản sao cuối cùng được đồng bộ hóa với nó.",
  "Server address unknown": "Địa chỉ máy chủ không xác định",
  "Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Ghép nối lại hoặc xuất bản sao lưu trước. Dù sao đi nữa, hãy giữ bản sao của những thay đổi này trên thiết bị này cho đến khi thiết bị kết nối lại với máy chủ này với tư cách là tài khoản này. Sau đó, chúng được thêm lại.",
  "Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Đăng nhập lại hoặc xuất bản sao lưu trước. Dù sao đi nữa, hãy giữ bản sao của những thay đổi này trên thiết bị này cho đến khi thiết bị kết nối lại với máy chủ này với tư cách là tài khoản này. Sau đó, chúng được thêm lại.",
  "{0} set · {1} work": "Bộ {0} · Công việc {1}",
  "Every exercise in this workout": "Mỗi bài tập trong bài tập này",
  "No sets are left in this workout, so there is nothing to save. Delete it from your history?": "Không có hiệp nào còn lại trong bài tập này nên không có gì để tiết kiệm. Xóa nó khỏi lịch sử của bạn?",
  "Photo, GIF or video": "Ảnh, GIF hoặc video",
  "Optional. A picture makes it easier to spot in a list.": "Tùy chọn. Một hình ảnh giúp bạn dễ dàng nhận ra hơn trong danh sách.",
  "Add": "Thêm",
  "Change": "Thay đổi",
  "Video or guide link (optional)": "Liên kết video hoặc hướng dẫn (tùy chọn)",
  "That link is not a web address": "Liên kết đó không phải là địa chỉ web",
  "Watch video": "Xem video",
  "Open link": "Mở liên kết",
  "Plays from YouTube, and only once you tap": "Phát từ YouTube và chỉ khi bạn nhấn",
  "Reset demo data": "Đặt lại dữ liệu demo",
  "Reset demo data?": "Đặt lại dữ liệu demo?",
  "Revised as you asked. Everything you did not question is exactly as it was.": "Đã sửa lại như bạn hỏi. Mọi thứ bạn không thắc mắc đều chính xác như nó vốn có.",
  "Same pattern, higher reps than day A.": "Cùng một mô hình, số lần lặp lại cao hơn ngày A.",
  "Self-host it in a minute →": "Tự lưu trữ nó sau một phút →",
  "Self-host openGym": "Tự tổ chức openGym",
  "Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.": "Các phiên họp đã diễn ra được khoảng mười lăm phút. Đây là phụ kiện ít bị mất nhất nếu giảm đi một bộ.",
  "Start the demo": "Bắt đầu bản demo",
  "The main lower-body driver, where most of the strength comes from.": "Người điều khiển phần thân dưới chính, nơi tạo ra phần lớn sức mạnh.",
  "The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.": "Những khuôn mẫu giống nhau, những biến thể khác nhau: đủ chồng chéo để tiến bộ, đủ khác biệt để luôn mới mẻ.",
  "The two big lower-body and pressing patterns first, while you are fresh.": "Hai thân dưới to và ép kiểu đầu tiên, khi bạn còn tươi.",
  "This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.": "Bản demo này chạy hoàn toàn trong trình duyệt của bạn trên dữ liệu mẫu. Không có gì được gửi đi bất cứ đâu. Đăng nhập bằng mật mã và đồng bộ hóa trên các thiết bị của bạn đi kèm với máy chủ openGym mà bạn nhận được bằng cách tự lưu trữ nó.",
  "Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.": "Ba điều đáng thay đổi và một điều đáng biết. Mọi thứ khác đều hoạt động tốt: squat và kéo đều tiến triển đúng tiến độ.",
  "Vertical pressing.": "Ép dọc.",
  "You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.": "Bạn đã chuyển phiên này sang thứ Bảy trong ba tuần liên tục. Tốt hơn là kế hoạch nói như vậy hơn là bạn tiếp tục ghi đè lên nó.",
  "You’re in the demo": "Bạn đang ở trong bản demo",
  "Copy as text": "Sao chép dưới dạng văn bản",
  "Copied": "Đã sao chép",
  "Could not copy": "Không thể sao chép",
  "Share as image": "Chia sẻ dưới dạng hình ảnh",
  "Opens in YouTube": "Mở trong YouTube",
  "That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.": "Loại tệp đó không được hỗ trợ. Sử dụng ảnh, GIF hoặc video MP4, MOV hoặc WebM.",
  "That file is too big. Max {0} MB.": "Tập tin đó quá lớn. Tối đa {0} MB.",
  "That video is too long. Max {0} seconds.": "Video đó quá dài. Tối đa {0} giây.",
  "That photo is too large to process on this device.": "Ảnh đó quá lớn để xử lý trên thiết bị này.",
  "You’re offline. Try again once you’re back online.": "Bạn đang ngoại tuyến. Hãy thử lại sau khi bạn trực tuyến trở lại.",
  "This browser cannot read that file.": "Trình duyệt này không thể đọc được tập tin đó.",
  "There is no room left on this device for that file.": "Không còn chỗ trống trên thiết bị này cho tập tin đó.",
  "This video may not play on every device. MP4 (H.264) plays everywhere.": "Video này có thể không phát trên mọi thiết bị. MP4 (H.264) phát ở mọi nơi.",
