  "{0} photos": "Ảnh {0}",
  "Your server was reached, but it refused the app’s request (CORS). If a reverse proxy such as Traefik adds CORS headers, let requests from {0} through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Máy chủ của bạn đã được truy cập nhưng nó từ chối yêu cầu của ứng dụng (CORS). Nếu một proxy ngược như Traefik thêm tiêu đề CORS, hãy để các yêu cầu từ {0} đến openGym không thay đổi. Xem “Ứng dụng điện thoại và CORS” trong docs/SELF_HOSTING.md.",
  "Could not reach {0}. Check the address and that this phone can reach it.": "Không thể truy cập {0}. Kiểm tra địa chỉ và điện thoại này có thể liên lạc được với nó không.",
  "The end of a rest or a hold buzzes like an alarm, even in silent mode.": "Khi kết thúc thời gian nghỉ hoặc chờ, âm thanh sẽ vang lên như chuông báo thức, ngay cả ở chế độ im lặng.",
  "Repeat today": "Lặp lại ngày hôm nay",
