  "{0} exercises no longer exist and were left out.": "Các bài tập {0} không còn tồn tại và bị loại bỏ.",
  "Show connection status": "Hiển thị trạng thái kết nối",
  "Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.": "Tắt: thanh ở trên cùng bị ẩn. Một dấu chấm trên Home vẫn cảnh báo khi đồng bộ bị kẹt.",
  "Connection problem": "Sự cố kết nối",
  "Backup folder": "Thư mục sao lưu",
