  "Use default folder": "Sử dụng thư mục mặc định",
  "This folder can’t be used for backups.": "Thư mục này không thể được sử dụng để sao lưu.",
  "openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym không thể ghi vào “{0}” nữa, vì vậy các bản sao sẽ chuyển đến Documents/openGym một lần nữa. Chọn lại thư mục để chuyển trở lại.",
  "openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym không thể ghi vào thư mục đã chọn nữa nên các bản sao sẽ chuyển đến Documents/openGym một lần nữa. Chọn lại thư mục để chuyển trở lại.",
  "Excuses don’t lift weights. Report for {0} tomorrow!": "Những lời bào chữa không nâng được tạ. Báo cáo về {0} vào ngày mai!",
  "Your muscles filed a missing-person report. Show up for {0}!": "Cơ bắp của bạn đã nộp báo cáo về người mất tích. Hãy đến với {0}!",
  "That address answers, but it isn’t an openGym server. Check the URL.": "Địa chỉ đó trả lời, nhưng đó không phải là máy chủ openGym. Kiểm tra URL.",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Địa chỉ đó trả lời, nhưng trang đăng nhập hoặc quy tắc proxy đã trả lời thay vì openGym. Để /api/ thông qua openGym không thay đổi. Xem “Ứng dụng điện thoại và CORS” trong docs/SELF_HOSTING.md.",
  "Switch sides": "Đổi bên",
  "Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.": "Lưu bản sao ngày tháng vào “{0}” sau khi kết thúc bài tập hoặc chỉnh sửa thói quen và giữ lại {1} mới nhất.",
  "Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.": "Lưu bản sao ngày tháng vào thư mục bạn đã chọn sau khi kết thúc bài tập hoặc chỉnh sửa thói quen và giữ {0} mới nhất.",
  "Plan options": "Tùy chọn kế hoạch",
