  "Back to a fixed week?": "Trở lại một tuần cố định?",
  "The loop stops. Your weekdays stay as they are, and the loop is saved for later.": "Vòng lặp dừng lại. Các ngày trong tuần của bạn vẫn như cũ và vòng lặp sẽ được lưu lại để sử dụng sau này.",
  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "Các thói quen trong một vòng lặp. Bất cứ điều gì tiếp theo sẽ tiếp tục cho đến khi bạn huấn luyện nó, bất kể ngày nào.",
