  "Guilt trip": "Chuyến đi tội lỗi",
  "Drill sergeant": "trung sĩ khoan",
  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "Một cú huých vào buổi tối của ngày đã lên kế hoạch mà không có gì được ghi lại, trong khoảng thời gian từ 20:00 đến 21:30. Sau 3 ngày bỏ lỡ liên tiếp, nó sẽ im ắng cho đến buổi tập tiếp theo của bạn.",
  "Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.": "Đã ghi lại bài tập trên thiết bị khác? Trước khi cảnh báo tắt, điện thoại sẽ kiểm tra máy chủ của bạn bất cứ khi nào điện thoại cho phép ứng dụng chạy ở chế độ nền. Mở ứng dụng luôn bắt kịp.",
  "Everything okay?": "Mọi chuyện ổn chứ?",
