  "No {0} today? Even a short session tomorrow counts.": "Hôm nay không có {0}? Ngay cả một phiên ngắn vào ngày mai cũng được tính.",
  "Rough day? {0} will keep. Tomorrow is a fresh start.": "Ngày khó khăn? {0} sẽ giữ nguyên. Ngày mai là một khởi đầu mới.",
  "Hey, {0} didn’t happen today. All good?": "Này, {0} đã không xảy ra hôm nay. Tất cả đều tốt chứ?",
  "I miss you": "tôi nhớ bạn",
  "{0} waited by the door all evening. For you.": "{0} đợi ở cửa suốt buổi tối. Dành cho bạn.",
  "The barbell asked about you today. I didn’t know what to say.": "Hôm nay thanh tạ đã hỏi về bạn. Tôi không biết phải nói gì.",
  "Was it something I said? {0} misses you.": "Có phải tôi đã nói điều gì đó không? {0} nhớ bạn.",
