  "This server only takes changes made at {0}. If you opened openGym at another address, whoever runs the server can set ORIGIN and RP_ID to match it (the self-hosting guide shows how).": "Máy chủ này chỉ nhận những thay đổi được thực hiện tại {0}. Nếu bạn đã mở openGym tại một địa chỉ khác, bất kỳ ai chạy máy chủ đều có thể đặt ORIGIN và RP_ID để khớp với địa chỉ đó (hướng dẫn tự lưu trữ sẽ hướng dẫn cách thực hiện).",
  "That code didn’t work. Codes last 5 minutes and work once, so grab a fresh one.": "Mã đó không hoạt động. Mã có thời hạn 5 phút và hoạt động một lần, vì vậy hãy lấy mã mới.",
