  "Another device synced while you were importing, so its changes were kept next to the backup.": "Một thiết bị khác đã được đồng bộ hóa trong khi bạn đang nhập nên những thay đổi của thiết bị đó được giữ bên cạnh bản sao lưu.",
  "Save as a backup file": "Lưu dưới dạng tập tin sao lưu",
  "Add this device's plan to your profile?": "Thêm gói của thiết bị này vào hồ sơ của bạn?",
  "Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Kế hoạch, ghi chú hoặc thẻ tập thể dục của bạn trên thiết bị này đã được thiết lập khi đăng xuất. Thêm chúng vào hồ sơ của bạn hoặc giữ hồ sơ chính xác như trên máy chủ.",
  "{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.": "Quy trình {0} đã được thực hiện trên thiết bị này khi đăng xuất. Thêm nó vào hồ sơ của bạn hoặc giữ hồ sơ chính xác như trên máy chủ.",
  "{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Các quy trình {0} đã được thực hiện trên thiết bị này khi đăng xuất. Thêm chúng vào hồ sơ của bạn hoặc giữ hồ sơ chính xác như trên máy chủ.",
  "This device, before signing in": "Thiết bị này, trước khi đăng nhập",
  "This device, before the update": "Thiết bị này, trước khi cập nhật",
