  "{0} second": "{0} giây",
  "{0} seconds": "{0} giây",
  "Scroll to 0:00 to turn the rest timer off.": "Di chuyển đến 0:00 để tắt bộ hẹn giờ nghỉ ngơi.",
  "The short break between the bursts of a rest-pause set.": "Khoảng nghỉ ngắn giữa các lần ngắt quãng của tập hợp tạm dừng nghỉ.",
  "Each exercise can have its own rest too. Set it in the exercise settings of a routine.": "Mỗi bài tập cũng có thể có phần nghỉ ngơi riêng. Đặt nó trong cài đặt bài tập của một thói quen.",
  "iPhone doesn’t let openGym vibrate. A sound or a flash does the job.": "iPhone không để openGym rung. Âm thanh hoặc đèn flash sẽ thực hiện công việc.",
  "No account, no cloud. Back it up anytime in Data & backup.": "Không có tài khoản, không có đám mây. Sao lưu nó bất cứ lúc nào trong Dữ liệu & sao lưu.",
  "Effort per set is off. Turn it on in Settings → Workout to keep rating.": "Nỗ lực mỗi bộ là tắt. Bật nó trong Cài đặt → Tập luyện để tiếp tục xếp hạng.",
  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "Nhập mã mà thiết bị khác của bạn hiển thị trong Cài đặt → Tài khoản → Thêm thiết bị khác. Thiết bị này sau đó sẽ nhận được mật mã riêng.",
  "Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.": "Mở Cài đặt → Tài khoản → “Ghép nối ứng dụng di động” trên trang web openGym mà bạn đã đăng nhập, sau đó nhập địa chỉ của trang đó và mã hiển thị ở đó.",
  "Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.": "Mở Cài đặt → Tài khoản → “Ghép nối ứng dụng di động” trên trang web openGym của bạn trong trình duyệt và nhập mã mới hiển thị ở đó. Những gì điện thoại này lưu giữ sẽ được hợp nhất vào tài khoản của bạn.",
  "Change the time left": "Thay đổi thời gian còn lại",
