  "Keep the logging form focused on the measurements you actually track.": "Giữ biểu mẫu ghi nhật ký tập trung vào các phép đo bạn thực sự theo dõi.",
  "Fill only what you measured today. Empty fields stay empty.": "Chỉ điền những gì bạn đo được ngày hôm nay. Các trường trống vẫn trống.",
