  "Greys show lighter in dark mode, so buttons don’t look switched off.": "Màu xám hiển thị nhạt hơn ở chế độ tối, vì vậy các nút trông không bị tắt.",
  "Greys show darker in light mode, so buttons don’t look switched off.": "Màu xám hiển thị tối hơn ở chế độ ánh sáng nên các nút trông không bị tắt.",
