  "Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.": "http:// đơn giản không được mã hóa. Tốt trên mạng gia đình của bạn, nhưng hãy sử dụng https:// nếu máy chủ của bạn có thể truy cập được từ internet.",
