  "Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.": "Hồ sơ, bài tập, trọng lượng cơ thể, ảnh và video của bạn sẽ bị xóa vĩnh viễn khỏi máy chủ này. Không có thao tác hoàn tác nào và thậm chí quản trị viên của bạn cũng không thể khôi phục chúng.",
  "Want a copy first? Export a backup. You can import it into openGym anytime.": "Muốn có một bản sao trước? Xuất bản sao lưu. Bạn có thể nhập nó vào openGym bất cứ lúc nào.",
