  "Not confirmed on this phone. Nothing was deleted.": "Chưa được xác nhận trên điện thoại này. Không có gì bị xóa.",
  "This phone has no screen lock, so the name you typed is the only check.": "Điện thoại này không có khóa màn hình nên tên bạn nhập là cách kiểm tra duy nhất.",
  "Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.": "Điện thoại của bạn sẽ kiểm tra xem đó có phải là bạn không (khuôn mặt, vân tay hoặc mật mã), sau đó tài khoản sẽ bị xóa.",
  "Never miss the end of a rest": "Không bao giờ bỏ lỡ phần cuối của thời gian nghỉ ngơi",
  "One quick thing": "Một điều nhanh chóng",
  "Rest timer, right on the lock screen": "Hẹn giờ nghỉ ngơi, ngay trên màn hình khóa",
  "Training reminders, only if you switch them on": "Lời nhắc luyện tập chỉ khi bạn bật chúng lên",
  "You can change it anytime in your phone’s settings.": "Bạn có thể thay đổi nó bất cứ lúc nào trong cài đặt điện thoại của bạn.",
  "openGym can tap you on the shoulder when a rest is over, even with the phone locked in your pocket.": "openGym có thể chạm vào vai bạn khi nghỉ ngơi xong, ngay cả khi điện thoại bị khóa trong túi.",
  "A good size for this screen.": "Một kích thước tốt cho màn hình này.",
  "Animation quality": "Chất lượng hoạt hình",
