  "Downloaded · {0}": "Đã tải xuống · {0}",
  "Downloading… {0}%": "Đang tải xuống… {0}%",
  "No animation, just the picture. Easy on battery.": "Không có hoạt hình, chỉ có hình ảnh. Dễ dàng về pin.",
  "Not downloaded": "Chưa tải xuống",
  "On this device": "Trên thiết bị này",
  "Sharper animations aren’t available on this device yet. The built-in ones work everywhere.": "Hình ảnh động sắc nét hơn chưa có sẵn trên thiết bị này. Những cái tích hợp hoạt động ở mọi nơi.",
  "Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.": "Hình ảnh động sắc nét hơn tải xuống một lần cho mỗi hình. Cho đến khi chúng ở đây, bạn sẽ thấy những cái được tích hợp sẵn nên không có gì bị bỏ trống.",
  "Still only": "Vẫn chỉ",
