  "Change your mind anytime under AI data sharing in the Coach menu.": "Thay đổi quyết định của bạn bất cứ lúc nào trong phần chia sẻ dữ liệu AI trong menu Huấn luyện viên.",
  "Nothing allowed yet": "Chưa có gì được phép",
