  "Through your server": "Thông qua máy chủ của bạn",
  "To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:": "Để trả lời, Huấn luyện viên sẽ gửi thông tin này qua máy chủ openGym của bạn tới {0}, một dịch vụ AI bên ngoài openGym mà quản trị viên máy chủ của bạn đã chọn:",
  "To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:": "Để trả lời, thiết bị này sẽ gửi thẳng thông tin này tới {0}, một dịch vụ AI bên ngoài openGym, bằng khóa API của bạn:",
  "Who may see your training": "Ai có thể xem chương trình đào tạo của bạn",
  "Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.": "Huấn luyện viên có thể gửi chương trình đào tạo của bạn đến ai từ thiết bị này. Rút nó ra và Huấn luyện viên sẽ hỏi lại lần sau. Một mô hình trên mạng của riêng bạn không bao giờ cần phải hỏi.",
  "With your API key": "Với khóa API của bạn",
  "Withdraw": "Rút tiền",
  "Withdrawn. The Coach will ask before it sends anything again.": "Đã rút tiền. Huấn luyện viên sẽ hỏi trước khi gửi lại bất cứ điều gì.",
  "Your answers to the Coach: goal, days, equipment, limits and injuries": "Câu trả lời của bạn cho Huấn luyện viên: mục tiêu, ngày thi đấu, trang bị, giới hạn và chấn thương",
  "Your body weight and goal weight": "Trọng lượng cơ thể và trọng lượng mục tiêu của bạn",
  "Your data, your call": "Dữ liệu của bạn, cuộc gọi của bạn",
  "Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.": "Tên, email và thông tin đăng nhập của bạn được giữ nguyên. {0} xử lý phần còn lại theo các điều khoản riêng tư của riêng mình.",
  "Your plan: routines, exercises, sets, reps and schedule": "Kế hoạch của bạn: thói quen, bài tập, hiệp, số lần lặp lại và lịch trình",
  "Your unit and language": "Đơn vị và ngôn ngữ của bạn",
  "Open on the watch": "Mở trên đồng hồ",
  "Start a workout on the phone and openGym pops up on your wrist.": "Bắt đầu tập luyện trên điện thoại và openGym bật lên trên cổ tay của bạn.",
  "Not allowed": "Không được phép",
  "Turn on Apple Health and the watch measures your heart rate for every set.": "Bật Apple Health và đồng hồ sẽ đo nhịp tim của bạn cho mỗi lần tập.",
  "Tap the wrist when a rest is over": "Chạm vào cổ tay khi hết thời gian nghỉ ngơi",
  "No Apple Watch paired with this iPhone": "Không có Apple Watch nào được ghép nối với iPhone này",
  "openGym is not on your Apple Watch yet. Install it in the Watch app.": "openGym chưa có trên Apple Watch của bạn. Cài đặt nó trong ứng dụng Đồng hồ.",
  "openGym is on your Apple Watch": "openGym có trên Apple Watch của bạn",
  "Last heard from the watch: {0}": "Lần nghe cuối cùng từ đồng hồ: {0}",
  "The watch hasn’t checked in yet. Open openGym on it once.": "Đồng hồ vẫn chưa được kiểm tra. Mở openGym trên đó một lần.",
  "Not allowed on the watch. Allow it in the Health app on your iPhone.": "Không được phép trên đồng hồ. Cho phép nó trong ứng dụng Sức khỏe trên iPhone của bạn.",
  "Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.": "Nhịp tim trong khi tập luyện và bên cạnh mỗi hiệp tập cũng như bài tập được lưu vào Apple Health. Đồng hồ hỏi một lần.",
  "Apple Health": "Sức khỏe táo",
