  "Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.": "Khởi động nhẹ nhàng nên họ có thể nghỉ ít hơn hoặc không nghỉ chút nào. Người cuối cùng vẫn được nghỉ ngơi đầy đủ trước khi tập công việc đầu tiên của bạn.",
