  "Your server keeps photos only on days with a workout. An update lets it keep them for any day.": "Máy chủ của bạn chỉ lưu giữ ảnh vào những ngày tập luyện. Một bản cập nhật cho phép nó giữ chúng bất kỳ ngày nào.",
