  "{0} photos know their day and go there. The others go on the day below.": "Ảnh {0} biết ngày của họ và đi đến đó. Những người khác đi vào ngày dưới đây.",
  "Every progress photo, lined up by date, for any day. Plus a before/after slider.": "Mỗi bức ảnh tiến độ, được sắp xếp theo ngày, cho bất kỳ ngày nào. Cộng với thanh trượt trước/sau.",
