  "Machine taken? Pick what you’d do instead, and a swap mid-workout offers these first.": "Máy bị lấy à? Thay vào đó, hãy chọn những gì bạn muốn làm và việc hoán đổi giữa buổi tập sẽ cung cấp những điều này trước tiên.",
