  "This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.": "Ứng dụng này không thể xác nhận bằng mật mã. Tạo mã trong trình duyệt để đăng nhập vào hồ sơ này hoặc thêm mật khẩu vào đó trước.",
