  "Your workouts in Apple Health": "Bài tập của bạn trong Apple Health",
  "openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.": "openGym có thể lưu mọi bài tập và cân nặng vào Apple Health, đồng thời Apple Watch có thể hiển thị nhịp tim của bạn khi bạn nâng tạ.",
