  "Your bar for this type, set in Your bars.": "Thanh của bạn cho loại này, được đặt trong Thanh của bạn.",
  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "Các thanh tạ tại phòng tập của bạn nặng bao nhiêu. Mọi bài tập với thanh đó đều đếm các đĩa từ nó, trừ khi bạn tự thực hiện bài tập đó. Tổng trọng lượng được ghi lại vẫn giữ nguyên.",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "Hầu hết các thang máy trong thư viện đều sử dụng “{0}”, một số thang máy sử dụng “{1}”. Một thanh ngắn cho tất cả chúng có nghĩa là thiết lập cả hai.",
  "Back to the standard bars": "Quay lại thanh tiêu chuẩn",
  "Standard bars. Tap if yours are lighter.": "Thanh tiêu chuẩn. Nhấn nếu của bạn nhẹ hơn.",
  "The last warm-up still gets the full rest before your first work set.": "Lần khởi động cuối cùng vẫn được nghỉ ngơi đầy đủ trước khi tập bài tập đầu tiên của bạn.",
