  "h": "h",
  "This device has 1 workout that is not in this backup. Replacing deletes it.": "Thiết bị này có 1 bài tập không có trong bản sao lưu này. Thay thế sẽ xóa nó.",
  "This device has {0} workouts that are not in this backup. Replacing deletes them.": "Thiết bị này có các bài tập {0} không có trong bản sao lưu này. Thay thế sẽ xóa chúng.",
  "Page {0} of {1}": "Trang {0} của {1}",
