  "Workouts, body weight and measurements": "Tập luyện, trọng lượng cơ thể và số đo",
  "One row per set, for Excel, Sheets, your coach or another app. openGym reads it back too.": "Mỗi bộ một hàng dành cho Excel, Trang tính, huấn luyện viên của bạn hoặc ứng dụng khác. openGym cũng đọc lại.",
  "Workouts (CSV)": "Bài tập (CSV)",
  "Body weight & measurements (CSV)": "Trọng lượng và số đo cơ thể (CSV)",
  "CSV exported": "Đã xuất CSV",
  "New in this workout": "Mới trong bài tập này",
  "Added to “{0}”": "Đã thêm vào “{0}”",
  "Add it to “{1}”": "Thêm nó vào “{1}”",
  "Add them to “{1}”": "Thêm chúng vào “{1}”",
  "Thinking about your question…": "Đang suy nghĩ về câu hỏi của bạn…",
  "This is the demo, so there is no AI model behind me. On your own server I answer questions like “{0}” with your plan, your last sessions and the workout you are doing right now.": "Đây là bản demo nên không có mô hình AI nào hỗ trợ tôi. Trên máy chủ của riêng bạn, tôi trả lời các câu hỏi như “{0}” về kế hoạch của bạn, các buổi tập cuối cùng và bài tập bạn đang thực hiện ngay bây giờ.",
  "Weight stack": "chồng trọng lượng",
  "The weights this machine really has, odd steps and all. Progression, deloads, warm-ups and the + and − buttons land only on these.": "Trọng lượng mà chiếc máy này thực sự có, các bước lẻ và tất cả. Tiến trình, tải xuống, khởi động và các nút + và − chỉ nằm trên những nút này.",
  "No list yet, so this exercise steps by its increment as usual.": "Chưa có danh sách nên bài tập này sẽ tăng dần theo từng bước như thường lệ.",
  "First ({0})": "Đầu tiên ({0})",
  "How many": "Có bao nhiêu",
  "Fill in": "Điền vào",
  "That’s the whole stack: {0} {1} is the heaviest it goes, so the weight stays.": "Đó là toàn bộ ngăn xếp: {0} {1} là thiết bị nặng nhất nên trọng lượng vẫn giữ nguyên.",
  "No code on your phone? It only has one while it’s connected to this server: Settings → Account → Connect to my server.": "Không có mã trên điện thoại của bạn? Nó chỉ có một khi được kết nối với máy chủ này: Cài đặt → Tài khoản → Kết nối với máy chủ của tôi.",
  "Signing in on your computer too needs your own server. Connect this phone to it, and Add another device then gives the computer a code.": "Đăng nhập trên máy tính của bạn cũng cần có máy chủ của riêng bạn. Kết nối điện thoại này với nó và Thêm thiết bị khác sau đó cung cấp mã cho máy tính.",
  "How hard it felt": "Cảm giác thật khó khăn biết bao",
  "Not rated yet": "Chưa được xếp hạng",
  "How hard did that feel?": "Cảm giác đó khó khăn thế nào?",
  "Tap how it felt, or type an exact {0}.": "Nhấn vào cảm giác hoặc nhập {0} chính xác.",
  "All out, nothing left": "Hết rồi, chẳng còn lại gì",
