  "Working, but steady": "Đang hoạt động nhưng ổn định",
  "Easy, you could chat the whole way": "Thật dễ dàng, bạn có thể trò chuyện suốt chặng đường",
  "I own no dumbbells": "Tôi không sở hữu quả tạ nào",
  "Slower than planned": "Chậm hơn kế hoạch",
  "Gaining faster than planned": "Đạt nhanh hơn kế hoạch",
  "Losing faster than planned": "Thất bại nhanh hơn kế hoạch",
  "Outside your range": "Ngoài phạm vi của bạn",
  "Enter a range first": "Nhập một phạm vi đầu tiên",
  "The trend through your weigh-ins of the last 3 weeks, so one salty dinner does not move it. Give it a range and the card tells you whether you are on pace.": "Xu hướng cân nặng của bạn trong 3 tuần qua, vì vậy một bữa tối mặn không ảnh hưởng đến cân nặng của bạn. Cung cấp cho nó một phạm vi và thẻ sẽ cho bạn biết liệu bạn có đang đi đúng hướng hay không.",
  "Lose": "Thua",
