  "Weeks": "Tuần",
  "Your plan from before it comes back.": "Kế hoạch của bạn từ trước khi nó quay trở lại.",
  "Your programmes": "Chương trình của bạn",
  "Your routines as a block of weeks, each week with its own %1RM or RPE.": "Công việc của bạn được tính theo khối tuần, mỗi tuần có %1RM hoặc RPE riêng.",
  "Your routines as a block of weeks, with starter programmes to try.": "Thói quen của bạn được tính theo tuần, với các chương trình khởi đầu để thử.",
