  "Strength block, 4 weeks": "Khối sức mạnh, 4 tuần",
  "The schedule in your plan right now becomes this programme’s.": "Lịch trình trong kế hoạch của bạn bây giờ sẽ trở thành của chương trình này.",
  "The week is the calendar week: week 1 is the one you start in. A pause holds it.": "Tuần là tuần dương lịch: tuần 1 là tuần bạn bắt đầu. Một khoảng dừng sẽ giữ nó.",
  "This programme is gone.": "Chương trình này đã biến mất.",
  "Three days of plain linear progression, with a deload every fourth week.": "Ba ngày tiến triển tuyến tính đơn giản, với một lần tải xuống vào mỗi tuần thứ tư.",
  "Three days on the 5×5 routines, a little heavier every week, then a light week to bounce back.": "Ba ngày thực hiện thói quen 5 × 5, mỗi tuần nặng hơn một chút, sau đó một tuần nhẹ để phục hồi.",
  "Upper / lower by effort, 6 weeks": "Tăng/giảm bằng nỗ lực, 6 tuần",
