  "No thanks": "Không, cảm ơn",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "Chọn một bài tập để xem các hiệp tốt nhất, mức tối đa ước tính và hướng tới của nó.",
  "Pointing at: {0}": "Chỉ vào: {0}",
