  "Records": "Hồ sơ",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "Lịch trình nói khi nào, thói quen nói những gì. Xây dựng kế hoạch của riêng bạn hoặc lấy một kế hoạch khởi đầu.",
