  "Profile default ({0})": "Cấu hình mặc định ({0})",
  "For gyms that mix kg and lb. This exercise is shown and typed in it everywhere, plates and steps included. Totals in Stats stay in {0}.": "Dành cho các phòng tập thể dục kết hợp giữa kg và lb. Bài tập này được hiển thị và gõ ở mọi nơi, bao gồm cả đĩa và các bước. Tổng số trong Thống kê vẫn ở {0}.",
  "Back to top": "Quay lại đầu trang",
  "A one-minute walk around the app": "Một phút đi bộ xung quanh ứng dụng",
  "A practice workout": "Một buổi luyện tập",
  "Backups, imports and syncing with your own server.": "Sao lưu, nhập và đồng bộ hóa với máy chủ của riêng bạn.",
  "Body map": "Bản đồ cơ thể",
  "Catch your breath": "Nín thở",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "Tìm kiếm hàng ngàn bài tập bằng ngôn ngữ của bạn. Gắn dấu sao cho mục yêu thích của bạn và chúng sẽ nổi lên trên cùng.",
  "See which muscles got the work and which still need rest. Tap one for details.": "Xem cơ nào đã làm việc và cơ nào vẫn cần nghỉ ngơi. Nhấn vào một để biết chi tiết.",
