  "Swipe a set": "Vuốt một bộ",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "Vuốt một học phần sang một bên để sao chép hoặc xóa nó. Số lượng của nó thậm chí còn mở ra nhiều hơn.",
  "The big Start button": "Nút Bắt đầu lớn",
  "The little body shows what each day works, so leg day can’t hide.": "Cơ thể nhỏ bé thể hiện những gì mỗi ngày hoạt động nên ngày tập chân không thể giấu được.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "Bộ hẹn giờ nghỉ ngơi sẽ tự bắt đầu. Thêm thời gian hoặc bỏ qua nếu bạn cảm thấy anh hùng.",
  "The ⋯ menu": "Trình đơn ⋯",
  "Theme, accent colour and what Home shows.": "Chủ đề, màu nhấn và nội dung Trang chủ hiển thị.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "Cái này là giả vờ, không có gì được cứu. Mỗi hàng là một hiệp: tạ, sau đó là số lần. Nhấn vào một số để thay đổi nó.",
  "Tick it off": "Đánh dấu nó đi",
  "Today at a glance": "Hôm nay nhìn thoáng qua",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "Phiên hôm nay diễn ra ở đây. Một lần nhấn và bạn sẽ nâng được. Ngày nghỉ nó báo như vậy, không có chuyến đi tội lỗi.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "Tập luyện vào các ngày cố định trong tuần hoặc thực hiện các thói quen của bạn theo vòng lặp trong đó lượt tiếp theo đang chờ bạn.",
  "Want a 1-minute tour?": "Bạn muốn một chuyến tham quan 1 phút?",
  "Week or rotation": "Tuần hoặc luân chuyển",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "Chúng tôi sẽ chỉ ra những điểm hay trên màn hình thực. Bảo lãnh bất cứ lúc nào.",
  "Workout settings, layouts, notes and extra exercises hide in here.": "Cài đặt tập luyện, bố cục, ghi chú và bài tập bổ sung ẩn ở đây.",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "Các bài tập, thành tích và mọi thứ bạn đã nâng được. Nó lấp đầy khi bạn đào tạo.",
  "You stopped halfway. Want to see the rest?": "Bạn đã dừng lại giữa chừng. Bạn muốn xem phần còn lại?",
  "Your data, your backups": "Dữ liệu của bạn, bản sao lưu của bạn",
  "Your progress": "Sự tiến bộ của bạn",
  "Your routines": "thói quen của bạn",
  "You’re set": "Bạn đã sẵn sàng",
  "Previous year": "Năm trước",
