  "With pictures": "Với hình ảnh",
  "A small picture next to each exercise, like a plan from the gym.": "Một bức tranh nhỏ bên cạnh mỗi bài tập, giống như một kế hoạch tập gym.",
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "Cái này tồn tại trong ứng dụng điện thoại openGym: Apple Health trên iPhone, Health Connect trên Android.",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Webhooks được gửi bởi máy chủ openGym của riêng bạn, vì vậy họ cần một cái. Kết nối thiết bị này với nó trong Tài khoản.",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "Webhooks đã tắt trên máy chủ này. Thêm INTEGrationS=webhook vào .env của nó và khởi động lại nó.",
  "The MCP server runs next to your own openGym server and reads your data there.": "Máy chủ MCP chạy bên cạnh máy chủ openGym của riêng bạn và đọc dữ liệu của bạn ở đó.",
  "Only what you switch on talks to anything. The rest stays out of your way.": "Chỉ những gì bạn bật mới nói chuyện với bất cứ điều gì. Phần còn lại vẫn tránh xa bạn.",
  "Could not reach your server": "Không thể truy cập máy chủ của bạn",
  "Tap to try again": "Nhấn để thử lại",
  "Disconnect {0}?": "Ngắt kết nối {0}?",
