  "Works with": "Hoạt động với",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "Không cần kết nối thêm: họ ghi vào {0} và openGym đọc từ đó.",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "Không cần kết nối thêm: họ viết thư cho Apple Health hoặc Health Connect và ứng dụng điện thoại openGym sẽ đọc từ đó.",
  "{0} has no direct line to openGym, and it does not need one.": "{0} không có đường dây trực tiếp tới openGym và nó cũng không cần đường dây này.",
  "How it gets here": "Làm thế nào nó đến được đây",
