  "Three goals a month on Home, sized to how you train.": "Ba mục tiêu mỗi tháng ở Trang chủ, phù hợp với cách bạn tập luyện.",
  "Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.": "http:// đơn giản chỉ hoạt động đối với một địa chỉ trên mạng gia đình của bạn, như 192.168.x.x, tên .local hoặc địa chỉ Tailscale 100.x. Mọi thứ trên internet đều cần https://.",
  "Plain http only on your home network": "Chỉ http đơn giản trên mạng gia đình của bạn",
  "Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.": "Tự do lặp lại những gì bạn đã làm lần trước, không có quy tắc tiến triển. Các quy tắc áp dụng cho các bài tập theo thói quen.",
  "Your watch thought this workout was forgotten. It keeps going here.": "Đồng hồ của bạn tưởng bài tập này đã bị lãng quên. Nó tiếp tục diễn ra ở đây.",
  "No rule (freestyle)": "Không có quy tắc (tự do)",
  "Freestyle keeps the numbers you set. A rule picked here applies to this workout only.": "Freestyle giữ những con số bạn đặt. Quy tắc được chọn ở đây chỉ áp dụng cho bài tập này.",
  "A number of ramp sets": "Một số bộ đoạn đường nối",
