  "Body": "Thân hình",
  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "Được thiết kế dựa trên trọng lượng tập luyện của bạn và được làm tròn phù hợp với đĩa tạ và tạ của phòng tập thể dục này. Một bài tập có thể tự chọn trong phần cài đặt của nó.",
  "Built from your work weight when the workout starts.": "Được xây dựng dựa trên trọng lượng tập luyện của bạn khi bắt đầu tập luyện.",
