  "It hurts, it’s taken, no time, feeling great": "Đau đớn, mất thời gian, cảm giác tuyệt vời",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Nó bị chèn ép, nên nhẹ hơn cho phần còn lại của nó. Dừng lại nếu nó vẫn còn đau.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Nó bị chèn ép, vì vậy các hiệp bạn còn lại sẽ chuyển sang một chuyển động tải cơ tương tự từ một góc độ nhẹ nhàng hơn.",
  "Keep these warm-ups": "Giữ những khởi động này",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Giữ. Lần khởi động tương tự vào lần tới, tùy theo trọng lượng bài tập của bạn.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Các tập hợp đã ghi và thói quen của bạn vẫn giữ nguyên như cũ. Huấn luyện viên không phải là bác sĩ hay nhà vật lý trị liệu. Nếu có gì đau, hãy hỏi chuyên gia.",
  "Looking at your workout…": "Nhìn vào quá trình tập luyện của bạn…",
