  "My own": "của riêng tôi",
  "New programme “{0}”": "Chương trình mới “{0}”",
  "Nothing at {0} {1}: that one starts cold.": "Không có gì ở {0} {1}: cái đó bắt đầu lạnh.",
  "Nothing could be applied any more.": "Không còn gì có thể áp dụng được nữa.",
  "Nothing to change. Carry on as planned.": "Không có gì để thay đổi. Hãy tiếp tục như kế hoạch.",
  "One set less keeps the session doable today and still counts.": "Ít hơn một hiệp sẽ giúp buổi tập hôm nay có thể thực hiện được và vẫn được tính.",
  "Only the warm-ups you plan yourself.": "Chỉ có phần khởi động bạn tự lên kế hoạch.",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "Tăng dần do trọng lượng tác phẩm: nhiều bậc hơn khi nặng, ít bậc hơn khi nhẹ.",
  "Remove warm-up {0}": "Loại bỏ phần khởi động {0}",
  "Revise programme “{0}”": "Sửa lại chương trình “{0}”",
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "Thói quen, bài tập, số hiệp và số lần lặp lại, khởi động, chương trình, lịch trình hàng tuần của bạn, cài đặt tiến độ và những gì phòng tập thể dục của bạn có thể tải.",
  "Running on empty": "Chạy trống",
  "Saved in the routine, scaled to your work weight": "Được lưu trong thói quen, được điều chỉnh theo trọng lượng công việc của bạn",
  "Saved under Plan → Programmes. It starts when you start it.": "Đã lưu trong Kế hoạch → Chương trình. Nó bắt đầu khi bạn bắt đầu nó.",
