  "Skip the rest of {0}": "Bỏ qua phần còn lại của {0}",
  "Something else": "Cái gì khác",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Squat, ép, hàng và bạn bè có được một đoạn đường dốc. Những lọn tóc và lọn tóc bắt đầu nguội.",
  "Straight into the work sets.": "Đi thẳng vào bộ công việc.",
  "That workout is over, so these can’t be applied any more.": "Buổi tập luyện đó đã kết thúc nên những điều này không thể áp dụng được nữa.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Ứng dụng sẽ tăng tốc theo trọng lượng bài tập của bạn: nhiều hiệp khởi động hơn khi nặng và ít hiệp hơn khi nhẹ, trên đĩa tập của bạn.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Giá đỡ đã được lấy, vì vậy hãy làm điều đó ở cuối. Phần còn lại của phiên không cần nó.",
  "There’s no workout running.": "Không có bài tập chạy nào.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Những bước khởi động này diễn ra trước khi tập luyện trong mỗi buổi tập, như một phần trọng lượng của bài tập, vì vậy chúng sẽ phát triển theo nó.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Đây là bản demo nên không có mô hình AI nào hỗ trợ tôi. Trên máy chủ của bạn, tôi đọc phiên làm việc của bạn và đề xuất những thay đổi như thế này.",
  "Warm-up {0}": "Khởi động {0}",
  "Warm-ups": "Khởi động",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "Có chuyện gì vậy? Huấn luyện viên gợi ý một số thay đổi đối với những gì còn lại của bài tập này. Các bộ đã ghi vẫn giữ nguyên như cũ.",
  "Where, and what movement hurts? (optional)": "Đau ở đâu và cử động thế nào? (tùy chọn)",
  "With {0} {1} today: {2}": "Với {0} {1} hôm nay: {2}",
  "You can keep training, the answer waits here and in the Coach.": "Bạn có thể tiếp tục luyện tập, câu trả lời đang chờ ở đây và trong Huấn luyện viên.",
  "You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.": "Bạn cảm thấy mạnh mẽ, vì vậy hãy cố gắng nhiều hơn một chút cho những gì còn lại. Không phải mức tối đa mới, chỉ là một cú huých.",
  "Your rows, as a share of the work weight, so they grow with it.": "Các hàng của bạn, như một phần của trọng lượng công việc, vì vậy chúng sẽ phát triển theo nó.",
  "Your workout moved on, so this one no longer fits.": "Quá trình tập luyện của bạn đã tiếp tục nên bài tập này không còn phù hợp nữa.",
  "deload included": "bao gồm tải xuống",
  "Spoken cues": "Tín hiệu nói",
  "Only while the app is on screen. Music turns down for a moment, it never stops.": "Chỉ khi ứng dụng ở trên màn hình. Âm nhạc tắt trong giây lát, nó không bao giờ dừng lại.",
  "This browser can’t speak. Try another one.": "Trình duyệt này không thể nói. Hãy thử một cái khác.",
  "Says your next set, “10 seconds” and “Rest is over”, and counts holds down.": "Nói hiệp tiếp theo của bạn là “10 giây” và “Đã nghỉ xong” và giữ nguyên số đếm.",
  "Speaking rate": "Tốc độ nói",
  "Slow": "Chậm",
  "Normal": "Bình thường",
  "Fast": "Nhanh",
